public class LiftArmCommand extends Command {
  private static final double kLiftSpeed = 0.5;
  private final Arm m_arm;

  public LiftArmCommand(Arm arm) {
    m_arm = arm;
    addRequirements(m_arm);
  }

  @Override
  public void execute() {
    m_arm.setSpeed(kLiftSpeed);
  }

  @Override
  public boolean isFinished() {
    return m_arm.atTargetPosition();
  }

  @Override
  public void end(boolean interrupted) {
    m_arm.setSpeed(kLiftSpeed);
  }
}
